/* =========================================================================
 * Palette sombre
 * ========================================================================= */
.theme-dark {
  /* Fonds, du plus sombre au plus clair */
  --fond-nuit:     #22282f; /* fonds de code */
  --fond-panneau:  #262c33; /* panneaux latéraux, barre d'onglets */
  --fond-alt:      #293038;
  --fond-page:     #2d343d; /* fond de la note */
  --fond-relief:   #353e48; /* survols, boutons */
  --fond-relief-2: #3c4651;
  --trait:         #3a434d; /* bordures */
  --trait-2:       #47515c;
  --trait-3:       #515b66;

  /* Textes (craie) */
  --texte:      #e2ded6; /* texte principal */
  --texte-vif:  #f2efe9; /* gras */
  --texte-doux: #abb2b9; /* texte secondaire */
  --texte-gris: #8a939c;
  --texte-pale: #78828c; /* texte discret */
  --code-texte: #d6d1c7;
  --sur-accent: #22282f; /* texte posé sur l'ocre */

  /* Couleurs */
  --ocre:       #dbb57c; /* accent : liens, cases, curseur */
  --ocre-vif:   #e7c796; /* survol */
  --ocre-titre: #dcbd8f; /* titres # */
  --bleu:       #a7c1de; /* titres ## */
  --sauge:      #a9c7a1; /* titres ###, tags, chaînes de code */
  --rose:       #e0aba6; /* code en ligne */

  /* Mêmes teintes en R, G, B (pour les transparences) */
  --ocre-rgb:  219, 181, 124;
  --sauge-rgb: 169, 199, 161;
  --texte-rgb: 226, 222, 214;
  --fond-rgb:  34, 40, 47;
  --voile: rgba(28, 31, 35, 0.6); /* derrière les fenêtres modales */
  --accent-hsl: 36, 57%, 67%;

  /* Couleurs nommées d'Obsidian (callouts, graphe, coloration du code) */
  --color-red-rgb: 214, 140, 140;     --color-red: #d68c8c;
  --color-orange-rgb: 217, 164, 126;  --color-orange: #d9a47e;
  --color-yellow-rgb: 217, 196, 138;  --color-yellow: #d9c48a;
  --color-green-rgb: 166, 190, 162;   --color-green: #a6bea2;
  --color-cyan-rgb: 146, 193, 192;    --color-cyan: #92c1c0;
  --color-blue-rgb: 157, 183, 207;    --color-blue: #9db7cf;
  --color-purple-rgb: 180, 169, 207;  --color-purple: #b4a9cf;
  --color-pink-rgb: 209, 163, 191;    --color-pink: #d1a3bf;
}

/* =========================================================================
 * Palette claire
 * ========================================================================= */
.theme-light {
  /* Fonds : la note est la plus claire, le cadre un cran plus soutenu */
  --fond-nuit:     #dfe4e8; /* fonds de code */
  --fond-panneau:  #e5e9ec; /* panneaux latéraux, barre d'onglets */
  --fond-alt:      #e9ecef;
  --fond-page:     #eef0f2; /* fond de la note */
  --fond-relief:   #dce2e7; /* survols, boutons */
  --fond-relief-2: #d3dae0;
  --trait:         #d3d9de; /* bordures */
  --trait-2:       #c4ccd3;
  --trait-3:       #aeb7bf;

  /* Textes (encre ardoise) */
  --texte:      #2f3740; /* texte principal */
  --texte-vif:  #1d242b; /* gras */
  --texte-doux: #5b6672; /* texte secondaire */
  --texte-gris: #6f7a85;
  --texte-pale: #7b8590; /* texte discret */
  --code-texte: #3a434d;
  --sur-accent: #eef0f2; /* texte posé sur l'ocre */

  /* Couleurs, assombries pour rester lisibles sur fond clair */
  --ocre:       #8c5f1f; /* accent : liens, cases, curseur */
  --ocre-vif:   #a3712a; /* survol */
  --ocre-titre: #946a2e; /* titres # */
  --bleu:       #3f6690; /* titres ## */
  --sauge:      #4c7246; /* titres ###, tags, chaînes de code */
  --rose:       #974842; /* code en ligne */

  /* Mêmes teintes en R, G, B (pour les transparences) */
  --ocre-rgb:  196, 146, 70;
  --sauge-rgb: 110, 150, 102;
  --texte-rgb: 47, 55, 64;
  --fond-rgb:  238, 240, 242;
  --voile: rgba(47, 55, 64, 0.35);
  --accent-hsl: 35, 64%, 34%;

  /* Couleurs nommées d'Obsidian (callouts, graphe, coloration du code) */
  --color-red-rgb: 176, 74, 74;       --color-red: #b04a4a;
  --color-orange-rgb: 168, 96, 46;    --color-orange: #a8602e;
  --color-yellow-rgb: 141, 116, 36;   --color-yellow: #8d7424;
  --color-green-rgb: 76, 114, 70;     --color-green: #4c7246;
  --color-cyan-rgb: 47, 122, 120;     --color-cyan: #2f7a78;
  --color-blue-rgb: 63, 102, 144;     --color-blue: #3f6690;
  --color-purple-rgb: 108, 90, 156;   --color-purple: #6c5a9c;
  --color-pink-rgb: 156, 79, 125;     --color-pink: #9c4f7d;
}

/* =========================================================================
 * Correspondances : les palettes ci-dessus appliquées à Obsidian (communes aux deux modes)
 * ========================================================================= */
.theme-dark,
.theme-light {
  /* Base Obsidian (sert aux éléments que le thème ne règle pas un par un) */
  --color-base-00: var(--fond-page);
  --color-base-05: var(--fond-alt);
  --color-base-10: var(--fond-alt);
  --color-base-20: var(--fond-panneau);
  --color-base-25: var(--fond-relief);
  --color-base-30: var(--trait);
  --color-base-35: var(--trait-2);
  --color-base-40: var(--trait-3);
  --color-base-50: var(--texte-pale);
  --color-base-60: var(--texte-gris);
  --color-base-70: var(--texte-doux);
  --color-base-100: var(--texte);
  --mono-rgb-0: var(--fond-rgb);
  --mono-rgb-100: var(--texte-rgb);

  /* Accent (indépendant de la couleur d'accent choisie dans les réglages) */
  --color-accent-hsl: var(--accent-hsl);
  --color-accent: var(--ocre);
  --color-accent-1: var(--ocre);
  --color-accent-2: var(--ocre-vif);

  /* Fonds */
  --background-primary: var(--fond-page);
  --background-primary-alt: var(--fond-alt);
  --background-secondary: var(--fond-panneau);
  --background-secondary-alt: var(--fond-nuit);
  --background-modifier-hover: rgba(var(--texte-rgb), 0.055);
  --background-modifier-active-hover: rgba(var(--ocre-rgb), 0.12);
  --background-modifier-border: var(--trait);
  --background-modifier-border-hover: var(--trait-2);
  --background-modifier-border-focus: var(--trait-3);
  --background-modifier-form-field: var(--fond-alt);
  --background-modifier-cover: var(--voile);

  /* Contrôles */
  --interactive-normal: var(--fond-relief);
  --interactive-hover: var(--fond-relief-2);
  --interactive-accent: var(--ocre);
  --interactive-accent-hover: var(--ocre-vif);
  --interactive-accent-hsl: var(--accent-hsl);

  /* Textes */
  --text-normal: var(--texte);
  --text-muted: var(--texte-doux);
  --text-faint: var(--texte-pale);
  --text-accent: var(--ocre);
  --text-accent-hover: var(--ocre-vif);
  --text-on-accent: var(--sur-accent);
  --text-on-accent-inverted: var(--texte);
  --text-selection: rgba(var(--ocre-rgb), 0.28);
  --text-highlight-bg: rgba(var(--ocre-rgb), 0.32);
  --text-highlight-bg-active: rgba(var(--ocre-rgb), 0.45);
  --caret-color: var(--ocre);
  --icon-color: var(--texte-doux);
  --icon-color-hover: var(--texte);
  --icon-color-active: var(--ocre);
  --icon-color-focused: var(--texte);

  /* Gras, italique */
  --bold-color: var(--texte-vif);
  --italic-color: inherit;

  /* Titres */
  --inline-title-color: var(--texte);
  --h1-color: var(--ocre-titre);
  --h2-color: var(--bleu);
  --h3-color: var(--sauge);
  --h4-color: var(--texte);
  --h5-color: var(--texte-doux);
  --h6-color: var(--texte-pale);

  /* Liens */
  --link-color: var(--ocre);
  --link-color-hover: var(--ocre-vif);
  --link-external-color: var(--ocre);
  --link-external-color-hover: var(--ocre-vif);
  --link-decoration: underline;
  --link-decoration-thickness: 1px;
  --link-unresolved-color: var(--ocre);
  --link-unresolved-opacity: 0.6;
  --link-unresolved-decoration-color: rgba(var(--ocre-rgb), 0.35);

  /* Tags en pilule, couleur sauge */
  --tag-color: var(--sauge);
  --tag-color-hover: var(--sauge);
  --tag-background: rgba(var(--sauge-rgb), 0.15);
  --tag-background-hover: rgba(var(--sauge-rgb), 0.24);
  --tag-border-width: 0px;

  /* Citations */
  --blockquote-border-color: rgba(var(--ocre-rgb), 0.85);
  --blockquote-color: var(--texte-doux);

  /* Listes, cases, séparateurs */
  --list-marker-color: var(--texte-pale);
  --list-marker-color-hover: var(--texte-doux);
  --list-marker-color-collapsed: var(--ocre);
  --checkbox-color: var(--ocre);
  --checkbox-color-hover: var(--ocre-vif);
  --checkbox-border-color: var(--texte-pale);
  --checkbox-border-color-hover: var(--texte-doux);
  --checkbox-marker-color: var(--sur-accent);
  --checklist-done-color: var(--texte-pale);
  --hr-color: var(--trait-2);

  /* Code */
  --code-background: var(--fond-nuit);
  --code-normal: var(--code-texte);
  --code-comment: var(--texte-pale);
  --code-function: var(--color-blue);
  --code-important: var(--color-red);
  --code-keyword: var(--color-purple);
  --code-operator: var(--texte-doux);
  --code-property: var(--color-cyan);
  --code-punctuation: var(--texte-gris);
  --code-string: var(--sauge);
  --code-tag: var(--color-pink);
  --code-value: var(--color-orange);

  /* Tableaux */
  --table-border-color: var(--trait);
  --table-header-background: var(--fond-alt);
  --table-header-background-hover: var(--fond-alt);
  --table-row-background-hover: rgba(var(--texte-rgb), 0.03);

  /* Interface : tout le cadre dans la même teinte, la note à part */
  --titlebar-background: var(--fond-panneau);
  --titlebar-background-focused: var(--fond-panneau);
  --tab-container-background: var(--fond-panneau);
  --tab-background-active: var(--fond-page);
  --tab-text-color: var(--texte-pale);
  --tab-text-color-active: var(--texte-doux);
  --tab-text-color-focused: var(--texte-doux);
  --tab-text-color-focused-active: var(--texte);
  --tab-outline-color: transparent;
  --tab-divider-color: transparent;
  --ribbon-background: var(--fond-panneau);
  --ribbon-background-collapsed: var(--fond-panneau);
  --status-bar-background: var(--fond-panneau);
  --status-bar-border-color: transparent;
  --status-bar-text-color: var(--texte-pale);
  --divider-color: var(--trait);
  --divider-color-hover: rgba(var(--ocre-rgb), 0.5);

  /* Explorateur de fichiers */
  --nav-item-color: var(--texte-doux);
  --nav-item-color-hover: var(--texte);
  --nav-item-color-active: var(--texte);
  --nav-item-color-selected: var(--texte);
  --nav-item-background-hover: rgba(var(--texte-rgb), 0.05);
  --nav-item-background-active: var(--fond-relief);
  --nav-item-background-selected: rgba(var(--ocre-rgb), 0.14);
  --nav-collapse-icon-color: var(--texte-pale);
  --nav-collapse-icon-color-collapsed: var(--texte-pale);

  /* Barres de défilement fines et discrètes */
  --scrollbar-bg: transparent;
  --scrollbar-thumb-bg: rgba(var(--texte-rgb), 0.08);
  --scrollbar-active-thumb-bg: rgba(var(--texte-rgb), 0.16);

  /* Graphe */
  --graph-line: var(--trait-2);
  --graph-node: var(--texte-doux);
  --graph-node-focused: var(--ocre);
  --graph-node-tag: var(--sauge);
  --graph-node-attachment: var(--color-blue);
  --graph-node-unresolved: var(--texte-pale);
  --graph-text: var(--texte);
}

/* =========================================================================
 * Typographie (commune aux deux modes)
 * ========================================================================= */
body {
  --font-text-theme: "Ardoise Sans", "Hanken Grotesk", "Atkinson Hyperlegible Next", "Segoe UI", sans-serif;
  --font-interface-theme: "Ardoise Sans", "Hanken Grotesk", "Atkinson Hyperlegible Next", "Segoe UI", sans-serif;
  --font-monospace-theme: "Ardoise Mono", "Geist Mono", "JetBrainsMono Nerd Font", "JetBrainsMono NF", Consolas, monospace;
  --ardoise-titre: "Ardoise Titre", "Fraunces", Georgia, serif;

  --line-height-normal: 1.65;
  --file-line-width: 680px;
  --bold-weight: 640;

  --inline-title-font: var(--ardoise-titre);
  --inline-title-size: 2.05em;
  --inline-title-weight: 600;
  --inline-title-line-height: 1.15;

  --h1-font: var(--ardoise-titre);
  --h1-size: 1.72em;
  --h1-weight: 600;
  --h1-line-height: 1.2;
  --h2-font: var(--ardoise-titre);
  --h2-size: 1.4em;
  --h2-weight: 570;
  --h2-line-height: 1.25;
  --h3-font: var(--ardoise-titre);
  --h3-size: 1.18em;
  --h3-weight: 600;
  --h3-line-height: 1.3;
  --h4-size: 1.02em;
  --h4-weight: 650;
  --h5-size: 0.84em;
  --h5-weight: 650;
  --h6-size: 0.8em;
  --h6-weight: 600;

  --tag-size: 0.86em;
  --tag-radius: 999px;
  --tag-padding-x: 0.6em;
  --tag-padding-y: 0.15em;
  --tag-decoration: none;
  --tag-decoration-hover: none;

  --blockquote-border-thickness: 2px;
  --code-size: 0.88em;
  --code-radius: 6px;
  --checkbox-radius: 4px;
  --hr-thickness: 1px;
  --callout-radius: 8px;
  --callout-border-width: 0px;
}

/* Fraunces en version douce : empattements arrondis, sans formes bancales */
.inline-title,
.markdown-rendered :is(h1, h2, h3),
.markdown-source-view.mod-cm6 :is(.HyperMD-header-1, .HyperMD-header-2, .HyperMD-header-3) {
  font-variation-settings: "SOFT" 100, "WONK" 0;
  letter-spacing: -0.005em;
}

/* Petits titres (h5, h6) en capitales espacées, comme des étiquettes */
.markdown-rendered :is(h5, h6),
.markdown-source-view.mod-cm6 :is(.HyperMD-header-5, .HyperMD-header-6) {
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

/* Dossiers un peu plus marqués que les fichiers */
.nav-folder-title {
  color: var(--text-normal);
  font-weight: 560;
}

/* Liens : soulignement discret qui se renforce au survol */
.markdown-rendered a {
  text-decoration-color: rgba(var(--ocre-rgb), 0.4);
  text-underline-offset: 0.18em;
}
.markdown-rendered a:hover {
  text-decoration-color: currentColor;
}

/* Code en ligne : petit cartouche, en rose */
.markdown-rendered :not(pre) > code {
  border-radius: var(--code-radius);
  padding: 0.1em 0.35em;
}
.markdown-rendered :not(pre) > code,
.cm-s-obsidian span.cm-inline-code:not(.cm-formatting) {
  color: var(--rose);
}

/* Blocs de code : un filet plutôt qu'une ombre */
.markdown-rendered pre {
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
}


